import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"思科网络技术学院教程 路由和交换基础实验手册","description":"路由与交换实验的阅读导引，关注拓扑、配置证据与故障复现。","frontmatter":{"title":"思科网络技术学院教程 路由和交换基础实验手册","description":"路由与交换实验的阅读导引，关注拓扑、配置证据与故障复现。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"路由与交换实验的阅读导引，关注拓扑、配置证据与故障复现。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"网络技术教程","link":"/life/personal/books/computing/network-technology"},"next":{"text":"计算机网络原理","link":"/life/personal/books/computing/network-principles"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网络技术教程","link":"/life/personal/books/computing/network-technology"},"next":{"text":"计算机网络原理","link":"/life/personal/books/computing/network-principles"}},"headers":[],"relativePath":"life/personal/books/computing/cisco-routing-switching-lab.md","filePath":"life/personal/books/computing/cisco-routing-switching-lab.md"}'),i={name:"life/personal/books/computing/cisco-routing-switching-lab.md"};function r(l,e,s,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="思科网络技术学院教程-路由和交换基础实验手册" tabindex="-1">思科网络技术学院教程 路由和交换基础实验手册 <a class="header-anchor" href="#思科网络技术学院教程-路由和交换基础实验手册" aria-label="Permalink to &quot;思科网络技术学院教程 路由和交换基础实验手册&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本手册的学习方向是把路由与交换概念落实到设备或仿真环境中。适合准备系统练习 Cisco 网络基础、希望掌握配置与排障流程的读者，也适合和网络原理教材对照阅读。</p><p>建议每个实验都保留“拓扑—配置—观察—解释”四部分。命令能执行，不等于目的已经达到；需要用路由表、接口状态、交换表和端到端访问结果验证。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>课程版本待确认。</strong> 书名能表明课程方向，但不能确定 NetAcad 课程代次、中文版版次或 IOS 环境。以下为本站主题导读，不是原书实验目录；实验编号、命令和设备型号以实际手册为准。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>书名明确指向思科网络技术学院教程体系。Cisco Press 的原版候选 Routing and Switching Essentials Lab Manual 署名 Cisco Networking Academy，2013年出版、版权年2014，ISBN 9781587133206；它的依据是课程编写与配套实验体系，不是某位个人作者的知名度。中文译者、课程代次和对应原版仍须核对版权页，不能把实验手册和 Companion Guide 正文教材混用。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合已认识 IP、子网和交换机作用、希望按拓扑进行路由交换实验的学生或初级网络工程师。理论薄弱时应先补分层和寻址；准备认证时还要核对当前考试与旧课程的差异。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>实验应验证的行为</th></tr></thead><tbody><tr><td>设备初始化</td><td>设置设备标识与管理访问，区分运行配置和启动配置。</td></tr><tr><td>接口与直连网络</td><td>检查接口状态、地址和直连路由，先验证本地链路再扩展拓扑。</td></tr><tr><td>静态与默认路由</td><td>为多网段建立往返路径，检查下一跳可达性和默认出口。</td></tr><tr><td>动态路由实验</td><td>观察邻接关系、学习到的路由和链路故障后的收敛过程；协议以原书版本为准。</td></tr><tr><td>交换与 VLAN</td><td>验证访问端口、Trunk 与 VLAN 归属，解释广播为何无法跨越某些边界。</td></tr><tr><td>VLAN 间路由</td><td>连接不同逻辑网段，核对网关与接口封装是否一致。</td></tr><tr><td>地址分配与转换</td><td>将 DHCP、NAT 的配置结果与客户端租约、转换记录对应起来。</td></tr><tr><td>综合排障</td><td>根据拓扑逐跳取证；让每项修改对应一个已验证的假设。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>配置是提出假设，状态输出才是验证假设。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>选一个两 VLAN 经路由互通的拓扑，先列出端口归属、Trunk、网关与回程，再逐项取证。每次只制造一个错误，例如遗漏 VLAN 或网关错误，记录不同症状，这比反复复制整段配置更能形成排障能力。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>厂商实验有明确步骤，便于建立操作习惯，但在仿真环境中成功不等于所有设备和 IOS 版本都一致。课程旧版的命令、默认行为及安全配置应在相应环境中重现；迁移时重新验证。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给愿意为每次实验留下拓扑和证据的人：真正可迁移的成果是定位路径，而非命令熟练度。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；需用版权页上的课程版次和 ISBN 核对原书目录。</li><li><a href="https://www.netacad.com/" target="_blank" rel="noopener noreferrer">Cisco Networking Academy</a>：课程与实验环境核对入口。</li><li><a href="https://www.ciscopress.com/" target="_blank" rel="noopener noreferrer">Cisco Press</a>：原版课程教材的出版信息核对入口；此处不指定尚未确认的版本。</li><li><a href="https://www.ciscopress.com/store/routing-and-switching-essentials-lab-manual-9781587133206" target="_blank" rel="noopener noreferrer">Cisco Press：Routing and Switching Essentials Lab Manual</a>：核实机构作者与原版候选；中文版对应关系待确认。</li></ul>',26)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
